<?php
session_start();require_once '../config/database.php';require_once 'lib.php';
if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;}
$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$status=(string)($_GET['status']??'');$allowed=['draft','approved','in_progress','completed','cancelled','needs_review','superseded'];$params=[(int)$railroad['id']];$where='sl.railroad_id=?';
if(in_array($status,$allowed,true)){$where.=' AND sl.status=?';$params[]=$status;}
$stmt=$pdo->prepare("SELECT sl.*,a.title_snapshot,a.operating_pattern,a.crew_name,a.assignment_number,s.session_number,s.operating_date,i.industry_name base_name,COUNT(m.id) move_rows,COUNT(DISTINCT m.equipment_id) car_count,GROUP_CONCAT(DISTINCT CONCAT(e.reporting_marks,' ',e.road_number) ORDER BY al.position SEPARATOR ', ') locomotives FROM operation_switch_lists sl JOIN operation_assignments a ON a.id=sl.assignment_id AND a.railroad_id=sl.railroad_id JOIN operating_sessions s ON s.id=sl.session_id AND s.railroad_id=sl.railroad_id LEFT JOIN industries i ON i.id=a.operating_base_industry_id AND i.railroad_id=a.railroad_id LEFT JOIN operation_switch_list_moves m ON m.switch_list_id=sl.id AND m.railroad_id=sl.railroad_id LEFT JOIN operation_assignment_locomotives al ON al.assignment_id=a.id LEFT JOIN equipment e ON e.id=al.equipment_id AND e.railroad_id=sl.railroad_id WHERE $where GROUP BY sl.id ORDER BY sl.updated_at DESC");$stmt->execute($params);$lists=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<?php include '../includes/header.php';?><title>Switch Lists / Work Orders</title><link rel="stylesheet" href="../assets/css/operations.css"></head><body><?php include '../includes/navbar.php';?><div class="tt-operations-shell"><?php include '../assets/components/sidebar.php';?><section class="tt-ops-page"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="tt-eyebrow">Operations</p><h1>Switch Lists / Work Orders</h1><p class="text-muted">Persistent plans, progress, revisions, closeouts, and history.</p></div><a class="btn btn-primary tt-mobile-full" href="sessions.php">Build Session</a></div><form class="mb-3"><label class="form-label me-2" for="workOrderStatus">Status</label><select id="workOrderStatus" name="status" class="form-select d-inline-block w-auto tt-mobile-full" onchange="this.form.submit()"><option value="">All</option><?php foreach($allowed as $value):?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=ttHtml(ttOperationsStatusLabel($value,'switch_list'))?></option><?php endforeach;?></select></form><div class="card"><div class="table-responsive tt-mobile-cards"><table class="table table-hover align-middle mb-0"><thead><tr><th>Work Order</th><th>Session / Date</th><th>Job</th><th>Base / Locomotives</th><th>Crew</th><th>Cars</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php foreach($lists as $list):?><tr><td data-label="Work Order"><a href="work_order.php?id=<?=(int)$list['id']?>"><strong><?=ttHtml($list['switch_list_number'])?></strong> · Rev <?=(int)$list['revision_number']?></a></td><td data-label="Session / Date"><?=ttHtml($list['session_number'])?><br><small><?=ttHtml($list['operating_date'])?></small></td><td data-label="Job"><?=ttHtml($list['title_snapshot'])?><br><small><?=ttHtml(ttJobTypes()[$list['operating_pattern']]??$list['operating_pattern'])?></small></td><td data-label="Base / Locomotives"><?=ttHtml($list['base_name']?:'—')?><br><small><?=ttHtml($list['locomotives']?:'None')?></small></td><td data-label="Crew"><?=ttHtml($list['crew_name']?:'Unassigned')?></td><td data-label="Cars"><?=(int)$list['car_count']?></td><td data-label="Status"><span class="badge tt-status-<?=ttHtml($list['status'])?>"><?=ttHtml(ttOperationsStatusLabel($list['status'],'switch_list'))?></span></td><td data-label="Updated"><?=ttHtml($list['updated_at'])?></td></tr><?php endforeach;?><?php if(!$lists):?><tr><td colspan="8" class="text-center text-muted py-5 tt-empty-row">No work orders match this filter.</td></tr><?php endif;?></tbody></table></div></div></section></div><?php include '../includes/footer.php';?>
